CREATE TABLE public.profiles (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, auth_id uuid NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', company text, niche text, location text, bio text, platforms text[] NOT NULL DEFAULT '{}', rate numeric CHECK(rate >= 0), followers bigint CHECK(followers >= 0), verified boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(name,company,niche,location,bio,platforms,rate,followers) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; GRANT USAGE, SELECT ON SEQUENCE public.profiles_id_seq TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(true);
CREATE POLICY profiles_edit ON public.profiles FOR UPDATE TO authenticated USING(auth_id=auth.uid()) WITH CHECK(auth_id=auth.uid());
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, profile_id bigint NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('brand','creator')));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(true);
CREATE FUNCTION public.my_profile_id() RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id FROM public.profiles WHERE auth_id=auth.uid() $$;
CREATE FUNCTION public.my_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM public.user_roles WHERE user_id=auth.uid() $$;
CREATE TABLE public.workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name))>0), owner_id bigint NOT NULL REFERENCES public.profiles(id), agency boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.workspaces TO authenticated; GRANT ALL ON public.workspaces TO service_role;
ALTER TABLE public.workspaces ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.workspace_members(workspace_id uuid REFERENCES public.workspaces(id) ON DELETE CASCADE, profile_id bigint REFERENCES public.profiles(id) ON DELETE CASCADE, PRIMARY KEY(workspace_id,profile_id));
GRANT SELECT ON public.workspace_members TO authenticated; GRANT ALL ON public.workspace_members TO service_role;
ALTER TABLE public.workspace_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_workspace_member(w uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=w AND profile_id=public.my_profile_id()) $$;
CREATE POLICY workspaces_read ON public.workspaces FOR SELECT TO authenticated USING(public.is_workspace_member(id));
CREATE POLICY members_read ON public.workspace_members FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.client_brands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, name text NOT NULL CHECK(length(trim(name))>0));
GRANT SELECT, INSERT ON public.client_brands TO authenticated; GRANT ALL ON public.client_brands TO service_role;
ALTER TABLE public.client_brands ENABLE ROW LEVEL SECURITY;
CREATE POLICY clients_read ON public.client_brands FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE POLICY clients_create ON public.client_brands FOR INSERT TO authenticated WITH CHECK(public.is_workspace_member(workspace_id) AND public.my_role()='brand');
CREATE TABLE public.campaigns(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, owner_id bigint NOT NULL REFERENCES public.profiles(id), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), client_brand_id uuid REFERENCES public.client_brands(id), title text NOT NULL CHECK(length(trim(title))>0), description text NOT NULL DEFAULT '', niche text NOT NULL, platform text NOT NULL CHECK(platform IN ('TikTok','Instagram','YouTube','Both')), budget numeric NOT NULL CHECK(budget>=0), deliverables text NOT NULL DEFAULT '', deadline timestamptz NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('draft','open','in_progress','closed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.campaigns TO authenticated; GRANT UPDATE(title,description,niche,platform,budget,deliverables,deadline,status) ON public.campaigns TO authenticated; GRANT ALL ON public.campaigns TO service_role; GRANT USAGE, SELECT ON SEQUENCE public.campaigns_id_seq TO authenticated,service_role;
ALTER TABLE public.campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY campaigns_read ON public.campaigns FOR SELECT TO authenticated USING(status <> 'draft' OR public.is_workspace_member(workspace_id));
CREATE POLICY campaigns_create ON public.campaigns FOR INSERT TO authenticated WITH CHECK(owner_id=public.my_profile_id() AND public.my_role()='brand' AND public.is_workspace_member(workspace_id));
CREATE POLICY campaigns_edit ON public.campaigns FOR UPDATE TO authenticated USING(public.is_workspace_member(workspace_id) AND public.my_role()='brand') WITH CHECK(public.is_workspace_member(workspace_id));
CREATE FUNCTION public.validate_campaign_client() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.client_brand_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.client_brands WHERE id=NEW.client_brand_id AND workspace_id=NEW.workspace_id) THEN RAISE EXCEPTION 'Client brand does not belong to this workspace'; END IF; RETURN NEW; END $$;
CREATE TRIGGER campaign_client BEFORE INSERT OR UPDATE ON public.campaigns FOR EACH ROW EXECUTE FUNCTION public.validate_campaign_client();
CREATE TABLE public.applications(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, campaign_id bigint NOT NULL REFERENCES public.campaigns(id), creator_id bigint NOT NULL REFERENCES public.profiles(id), pitch text NOT NULL CHECK(length(trim(pitch))>0), rate numeric NOT NULL CHECK(rate>0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(campaign_id,creator_id));
GRANT SELECT,INSERT ON public.applications TO authenticated; GRANT UPDATE(status) ON public.applications TO authenticated; GRANT ALL ON public.applications TO service_role; GRANT USAGE, SELECT ON SEQUENCE public.applications_id_seq TO authenticated,service_role;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY applications_read ON public.applications FOR SELECT TO authenticated USING(creator_id=public.my_profile_id() OR EXISTS(SELECT 1 FROM public.campaigns c WHERE c.id=campaign_id AND public.is_workspace_member(c.workspace_id)));
CREATE POLICY applications_create ON public.applications FOR INSERT TO authenticated WITH CHECK(creator_id=public.my_profile_id() AND public.my_role()='creator' AND status='pending' AND EXISTS(SELECT 1 FROM public.campaigns c WHERE c.id=campaign_id AND c.status='open'));
CREATE POLICY applications_decide ON public.applications FOR UPDATE TO authenticated USING(public.my_role()='brand' AND EXISTS(SELECT 1 FROM public.campaigns c WHERE c.id=campaign_id AND public.is_workspace_member(c.workspace_id))) WITH CHECK(public.my_role()='brand' AND EXISTS(SELECT 1 FROM public.campaigns c WHERE c.id=campaign_id AND public.is_workspace_member(c.workspace_id)));
CREATE TABLE public.messages(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, sender_id bigint NOT NULL REFERENCES public.profiles(id), receiver_id bigint NOT NULL REFERENCES public.profiles(id), body text NOT NULL, is_read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.messages TO authenticated; GRANT UPDATE(is_read) ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_read ON public.messages FOR SELECT TO authenticated USING(public.my_profile_id() IN(sender_id,receiver_id));
CREATE POLICY messages_mark ON public.messages FOR UPDATE TO authenticated USING(receiver_id=public.my_profile_id()) WITH CHECK(receiver_id=public.my_profile_id());
CREATE TABLE public.notifications(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id bigint NOT NULL REFERENCES public.profiles(id), title text NOT NULL, body text NOT NULL, read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.notifications TO authenticated; GRANT UPDATE(read) ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_read ON public.notifications FOR SELECT TO authenticated USING(user_id=public.my_profile_id());
CREATE POLICY notifications_mark ON public.notifications FOR UPDATE TO authenticated USING(user_id=public.my_profile_id()) WITH CHECK(user_id=public.my_profile_id());
CREATE TABLE public.saved_campaigns(user_id bigint REFERENCES public.profiles(id) ON DELETE CASCADE, campaign_id bigint REFERENCES public.campaigns(id) ON DELETE CASCADE, PRIMARY KEY(user_id,campaign_id));
GRANT SELECT,INSERT,DELETE ON public.saved_campaigns TO authenticated; GRANT ALL ON public.saved_campaigns TO service_role;
ALTER TABLE public.saved_campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY saves_read ON public.saved_campaigns FOR SELECT TO authenticated USING(user_id=public.my_profile_id());
CREATE POLICY saves_create ON public.saved_campaigns FOR INSERT TO authenticated WITH CHECK(user_id=public.my_profile_id());
CREATE POLICY saves_delete ON public.saved_campaigns FOR DELETE TO authenticated USING(user_id=public.my_profile_id());
CREATE FUNCTION public.create_account_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(auth_id,name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'name','')); RETURN NEW; END $$;
CREATE TRIGGER account_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account_profile();
CREATE FUNCTION public.complete_onboarding(account_role text, display_name text, workspace_name text DEFAULT '', is_agency boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p bigint; w uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF account_role NOT IN ('brand','creator') OR length(trim(display_name))=0 THEN RAISE EXCEPTION 'Invalid account details'; END IF; SELECT id INTO p FROM public.profiles WHERE auth_id=auth.uid() FOR UPDATE; IF p IS NULL THEN RAISE EXCEPTION 'Profile unavailable'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Account already configured'; END IF; UPDATE public.profiles SET name=trim(display_name),company=CASE WHEN account_role='brand' THEN trim(workspace_name) ELSE NULL END WHERE id=p; INSERT INTO public.user_roles VALUES(auth.uid(),p,account_role); IF account_role='brand' THEN IF length(trim(workspace_name))=0 THEN RAISE EXCEPTION 'Workspace name required'; END IF; INSERT INTO public.workspaces(name,owner_id,agency) VALUES(trim(workspace_name),p,is_agency) RETURNING id INTO w; INSERT INTO public.workspace_members VALUES(w,p); INSERT INTO public.client_brands(workspace_id,name) VALUES(w,trim(workspace_name)); END IF; END $$;
CREATE FUNCTION public.create_workspace(workspace_name text,is_agency boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p bigint; w uuid; BEGIN IF public.my_role() IS DISTINCT FROM 'brand' OR length(trim(workspace_name))=0 THEN RAISE EXCEPTION 'Brand account and workspace name required'; END IF; p:=public.my_profile_id(); INSERT INTO public.workspaces(name,owner_id,agency) VALUES(trim(workspace_name),p,is_agency) RETURNING id INTO w; INSERT INTO public.workspace_members VALUES(w,p); RETURN w; END $$;
CREATE FUNCTION public.add_workspace_member(w uuid,member_profile_id bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=w AND owner_id=public.my_profile_id()) THEN RAISE EXCEPTION 'Only the workspace owner can add members'; END IF; IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE profile_id=member_profile_id AND role='brand') THEN RAISE EXCEPTION 'Member must have a brand account'; END IF; INSERT INTO public.workspace_members VALUES(w,member_profile_id) ON CONFLICT DO NOTHING; END $$;
CREATE FUNCTION public.application_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner bigint; BEGIN IF TG_OP='INSERT' THEN SELECT owner_id INTO owner FROM public.campaigns WHERE id=NEW.campaign_id; INSERT INTO public.notifications(user_id,title,body) VALUES(owner,'New proposal','A creator applied to your campaign.'); ELSIF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.notifications(user_id,title,body) VALUES(NEW.creator_id,'Proposal updated','Your proposal is now '||NEW.status||'.'); END IF; RETURN NEW; END $$;
CREATE TRIGGER proposal_notifications AFTER INSERT OR UPDATE ON public.applications FOR EACH ROW EXECUTE FUNCTION public.application_notification();
REVOKE ALL ON FUNCTION public.my_profile_id(),public.my_role(),public.is_workspace_member(uuid),public.complete_onboarding(text,text,text,boolean),public.create_workspace(text,boolean),public.add_workspace_member(uuid,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.my_profile_id(),public.my_role(),public.is_workspace_member(uuid),public.complete_onboarding(text,text,text,boolean),public.create_workspace(text,boolean),public.add_workspace_member(uuid,bigint) TO authenticated;
REVOKE ALL ON FUNCTION public.create_account_profile(),public.application_notification(),public.validate_campaign_client() FROM PUBLIC;
CREATE INDEX campaigns_workspace_idx ON public.campaigns(workspace_id); CREATE INDEX applications_campaign_idx ON public.applications(campaign_id); CREATE INDEX notifications_user_idx ON public.notifications(user_id); CREATE INDEX messages_receiver_idx ON public.messages(receiver_id);